    "pd.compat.btn": "Check device compatibility",
    "faq.q1": "What is LemonSIM?",
    "faq.a1": "LemonSIM sells prepaid travel data: eSIMs for 13 destinations and physical SIM cards for the USA, Europe and Japan, so you can get online abroad without paying your home carrier's roaming fees.",
    "faq.q2": "What's the difference between an eSIM and a physical SIM card?",
    "faq.a2": "An eSIM is a digital SIM: you add it to your phone by scanning a QR code, so nothing has to be shipped. A physical SIM card goes into your phone's SIM tray. Choose an eSIM if your phone supports it, or a SIM card if it doesn't.",
    "faq.q3": "Which destinations do you cover?",
    "faq.a3": "eSIMs: USA, Canada, Mexico, Costa Rica, Dominica, Japan, Thailand, Vietnam, Europe, Turkey, UAE, Egypt and Morocco. SIM cards: USA, Europe and Japan. <a href=\"esim.html\">See all eSIM plans</a> or <a href=\"sim-card.html\">SIM cards</a>.",
    "faq.q4": "Does my phone support eSIM?",
    "faq.a4": "Your phone needs eSIM support and must be carrier-unlocked. Quick check: dial *#06#. If a 32-digit EID appears, the phone has eSIM hardware. You can also <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">check your phone model</a>.",
    "faq.q5": "How will I receive my eSIM?",
    "faq.a5": "By email after payment, with your QR code and installation instructions.",
    "faq.q6": "When should I install my eSIM?",
    "faq.a6": "Install it on Wi-Fi shortly before you need mobile data. Your plan starts as soon as you install it, and the day you install it counts as day 1. Each new plan day begins at noon EDT (11:00 a.m. EST), wherever you are. Turning the eSIM off doesn't pause it. Don't delete it afterwards: a QR code can usually be used only once.",
    "faq.q7": "How do I start using it when I land?",
    "faq.a7": "Turn the eSIM line on, turn on data roaming for that line, and choose it for mobile data. It usually connects within a few minutes. Step-by-step: <a href=\"how-esim-works.html\">How eSIM Works</a>.",
    "faq.q8": "Can I keep my own number for calls and WhatsApp?",
    "faq.a8": "Yes, on dual-SIM phones. Keep your home SIM on for calls and texts and use LemonSIM for data. Turn off data roaming on your home line to avoid roaming charges. WhatsApp stays linked to your existing number.",
    "faq.q9": "How do I set up a physical SIM card?",
    "faq.a9": "Put it in an unlocked phone, turn on data roaming, and wait a few minutes. If there is still no data, set the APN to \"plus\". Step-by-step: <a href=\"how-sim-card-works.html\">How SIM Card Works</a>.",
    "faq.q10": "Which networks will I use?",
    "faq.a10": "LemonSIM uses partner networks in each destination. Every plan page lists them, and your phone connects to the best available one automatically.",
    "faq.q11": "Can I use hotspot?",
    "faq.a11": "Yes. All LemonSIM plans allow hotspot (tethering), so you can share your data with a laptop or another device.",
    "faq.q12": "Can I top up my plan?",
    "faq.a12": "Physical SIM cards can be topped up at <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a>. eSIM plans can't be topped up: if you need more data or days, buy a new eSIM plan.",
    "faq.q13": "My eSIM isn't working. What should I check?",
    "faq.a13": "Make sure the LemonSIM line is on, data roaming is on for it, and it's selected for mobile data. Then turn airplane mode on and off, or restart the phone. Still stuck? See <a href=\"support.html\">Support</a> or email <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a> with your destination, phone model and order number.",
    "faq.q14": "Can I cancel or get a refund?",
    "faq.a14": "We don't offer change-of-mind refunds except where required by law, so please <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">check your phone</a> before buying. If your plan doesn't work, email <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a> (support is available 24/7): we'll troubleshoot and offer a replacement or refund where appropriate or required by law. We refund duplicate charges and orders we can't deliver, and your legal rights are unaffected. Read the <a href=\"refund-policy.html\">Refund Policy</a>.",
    "faq.q15": "How do I contact LemonSIM?",
    "faq.a15": "Email <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>. Support is available 24/7. You can also use the <a href=\"contact.html#contact\">contact page</a>.",
    "ge.intro": "Set up your eSIM in two parts: before you leave, and when you land.",
    "ge.before": "Get ready",
    "ge.land": "When you land",
    "ge.s1": "Check your phone",
    "ge.s1.p": "It needs eSIM support and must be carrier-unlocked. <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">Check your phone model</a>.",
    "ge.s2": "Know when your plan starts",
    "ge.s2.p": "Your plan starts when you install the eSIM, and the day you install it counts as day 1. Each new plan day begins at noon Eastern Daylight Time (EDT), or 11:00 a.m. Eastern Standard Time (EST), regardless of your location. For example, a 7-day plan installed at 8:00 a.m. Eastern Time on May 1 expires at noon Eastern Time on May 7.",
    "ge.s3": "Install it on Wi-Fi",
    "ge.s3.p": "Shortly before you need mobile data, scan the QR code from your email.",
    "ge.s3.l1": "iPhone: Settings › Cellular (or Mobile Service) › Add eSIM",
    "ge.s3.l2": "Android: Settings › Connections › SIM manager › Add eSIM (names vary by brand)",
    "ge.s3.l3": "Don't delete the eSIM later: a QR code can usually be used only once.",
    "ge.s4": "Label the line",
    "ge.s4.p": "Name it, for example \"LemonSIM Japan\", so it's easy to pick for mobile data. Turning it off doesn't pause the plan.",
    "ge.s5": "Turn it on with data roaming",
    "ge.s5.p": "Switch the LemonSIM line on and turn on data roaming for that line.",
    "ge.s6": "Use it for mobile data",
    "ge.s6.p": "Choose LemonSIM for mobile data. Your home SIM can stay on for calls and texts.",
    "ge.s7": "Turn off roaming on your home line",
    "ge.s7.p": "Turn off data roaming on your home SIM so your home carrier doesn't charge you.",
    "ge.help": "No connection after a few minutes? See <a href=\"support.html\">Support</a>.",
    "gs.intro": "Check your device, insert the card, and connect. APN settings are only needed if data doesn't start on its own.",
    "gs.s1": "Check your device",
    "gs.s1.p": "It must be carrier-unlocked, support 4G LTE (5G phones work too) and have a free SIM slot. Cards are available in nano, micro and standard sizes.",
    "gs.dev": "Works in: phones · tablets · 4G Wi-Fi routers and pocket Wi-Fi · 4G security and trail cameras · car and pet GPS trackers · 4G walkie-talkies",
    "gs.s2": "Insert the card and connect",
    "gs.s2.l1": "Turn the device off and insert the LemonSIM card. Keep your home SIM somewhere safe.",
    "gs.s2.l2": "Turn the device on and turn on data roaming.",
    "gs.s2.l3": "Wait a few minutes for it to connect.",
    "gs.s3": "No data? Set the APN",
    "gs.s3.p": "The APN is usually set automatically. If there is still no data, set it to \"plus\" with no username or password.",
    "gs.s3.l1": "iPhone: Settings › Cellular › Cellular Data Network › APN: plus",
    "gs.s3.l2": "Android: Settings › Connections › Mobile networks › Access Point Names › add \"plus\" (names vary by brand)",
    "gs.help": "Still no connection? See <a href=\"support.html\">Support</a>.",
