    "cmp.none.p": "That doesn't mean it can't work. Try the *#06# check or look in Settings (below). If your phone has no eSIM, a <a href=\"sim-card.html\">LemonSIM physical SIM card</a> is an option.",
    "cmp.note.apple": "iPhones sold in mainland China usually don't support eSIM, and many Hong Kong and Macau models don't either. iPads: Wi-Fi + Cellular models only.",
    "cmp.note.samsung": "Most models sold in China, Hong Kong, Taiwan or South Korea don't support eSIM, and neither do US versions of the S20, S21 and Note 20 Ultra.",
