    "cmp.unlock": "What does carrier-unlocked mean?",
    "cmp.unlock.p": "A locked phone only works with the carrier that sold it. On iPhone, Settings › General › About › Carrier Lock should say \"No SIM restrictions\". On Android, ask your carrier or try another carrier's SIM.",
    "cmp.foot": "Model list checked against manufacturer and industry lists on 2 Nov 2026. It isn't complete and regional versions differ, so the *#06# check on your phone is the final word.",
    "cmp.sim.intro": "A LemonSIM card works in a phone or device that:",
