    "cmp.sim.dual": "On dual-SIM phones you can usually keep your home SIM in the other slot. Some phones share a slot between a second SIM and a memory card.",
    "cmp.sim.esim": "Does your phone support eSIM? <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">Check here</a>. An eSIM needs no delivery.",
    "cmp.close": "Close",
    "faq.q16": "How long does SIM card delivery take?",
    "faq.a16": "Usually 5–7 days, so order early enough to get it before you travel. You enter your delivery address at checkout. Cards are available in nano, micro and standard sizes; most recent phones use nano.",
    "ct.hours": "Support is available 24/7.",
    "pd.buy.esim": "Check that your phone is unlocked and <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">supports eSIM</a> before buying. No change-of-mind refunds except where required by law. <a href=\"refund-policy.html\">Refund Policy</a>",
    "pd.buy.sim": "Check that your phone is unlocked and <a href=\"esim-compatible-phones.html#sim\" data-compat=\"sim\">works with SIM cards</a> before buying. Delivery usually takes 5–7 days. No change-of-mind refunds except where required by law. <a href=\"refund-policy.html\">Refund Policy</a>",
    "rf.h1": "Refund Policy",
    "rf.intro": "We want every plan to work, and if one doesn't, we fix it first. Please read this before you buy.",
    "rf.note": "Demo draft, November 2026. The legal wording must be reviewed before it goes live.",
    "rf.toc": "On this page",
    "rf.s1": "Before you buy",
    "rf.s1.p": "Check that your phone is unlocked and <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">supports eSIM</a> (or <a href=\"esim-compatible-phones.html#sim\" data-compat=\"sim\">works with SIM cards</a>), and check your travel dates. An eSIM plan starts as soon as you install it, so install it shortly before you need data. We don't offer change-of-mind refunds, except where required by law. That includes trips that change or are cancelled, plans you no longer need, the wrong destination, and phones that are locked, jailbroken, rooted or not compatible.",
    "rf.s2": "If your plan doesn't work",
    "rf.s2.p": "Email <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>. Support is available 24/7. Include your order number, destination, phone model and screenshots, and don't delete the eSIM. We'll troubleshoot first. If we're responsible and can't fix the problem, we'll offer a replacement or a refund as appropriate. You can get a refund sooner where the law entitles you to one. Store credit is only given if you choose it.",
    "rf.s3": "Duplicate charges and failed delivery",
    "rf.s3.p": "We refund duplicate charges and payments for orders we can't deliver.",
    "rf.s4": "Cancellation rights",
    "rf.s4.p": "Where applicable law gives you a right to cancel, for example for physical SIM cards in some countries, we honour it, including any required refund of delivery charges. Otherwise, we don't offer change-of-mind returns.",
    "rf.s5": "How refunds are paid",
    "rf.s5.p": "Refunds go to your original payment method within applicable legal deadlines. Your payment provider may take extra time to show the credit.",
    "rf.s6": "Your legal rights",
    "rf.s6.p": "Nothing in this policy limits rights that can't be excluded under applicable consumer law.",
    "cmp.need3": "Not be jailbroken (iPhone) or rooted (Android)",
    "val.esim": "Starts when you install the eSIM; the installation day counts as day 1. Plan days reset at noon EDT / 11:00 a.m. EST. Turning the eSIM off doesn't pause it.",
    "val.sim": "Plan days reset at noon EDT / 11:00 a.m. EST, regardless of your location.",
