    "cmp.fast.note": "Shows eSIM support only.",
    "cmp.listnote": "List updated Nov 2026. Regional models vary.",
    "rv.line": "Last reviewed by the LemonSIM Support team · November 3, 2026 · <a href=\"editorial-policy.html\">Editorial standards</a>",
    "ed.h1": "Editorial standards",
    "ed.intro": "How we write, check and correct the information on this website.",
    "ed.s1": "Who is responsible",
    "ed.s1.p": "LemonSIM's support and content team is responsible for our shopping information and travel connectivity guides.",
    "ed.s2": "How we check information",
    "ed.s2.p": "Before publishing or reviewing a guide, we check relevant manufacturer documentation, carrier or partner network information, and LemonSIM plan details. We link to sources where they help you verify a claim. Our <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">compatibility list</a> is a reference, not a guarantee for every regional phone model.",
    "ed.s3": "Reviews and dates",
    "ed.s3.p": "\"Last reviewed\" means our team checked the page's factual information and relevant sources on that date. A review may confirm that no changes are needed. We change the review date only after completing a review.",
    "ed.s4": "Corrections",
    "ed.s4.p": "To report an error, email <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a> with the page link and the detail you believe is incorrect. We will investigate reports and correct confirmed errors. When we review the full page, we update its review date.",
    "ed.s5": "Commercial transparency",
    "ed.s5.p": "LemonSIM sells the plans described on this website. Our guides explain our products and their requirements. We will clearly label any sponsored content or paid placement.",
    "ab.w.eyebrow": "Working with us",
    "ab.w.h2": "What you can expect from LemonSIM",
    "ab.w1t": "What we sell",
    "ab.w1p": "eSIM plans for 13 destinations; SIM cards for the USA, Europe and Japan. Every plan page lists data, validity, price and partner networks.",
    "ab.w2t": "Help when you need it",
    "ab.w2p": "Email support is available 24/7 at <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>, before and during your trip.",
    "ab.w3t": "Clear policies",
    "ab.w3p": "Read our <a href=\"refund-policy.html\">Refund Policy</a>, <a href=\"terms-of-service.html\">Terms</a>, <a href=\"privacy-policy.html\">Privacy Policy</a> and <a href=\"editorial-policy.html\">Editorial standards</a> before you buy.",
    "ab.w4t": "Secure payment",
    "ab.w4p": "Checkout is powered by Stripe, so your full card number goes to Stripe, not to us.",
    "ab.w5t": "Find us",
    "ab.w5p": "Follow LemonSIM on <a href=\"https://www.facebook.com/share/1DepLp294g/?mibextid=wwXIfr\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a>, <a href=\"https://instagram.com/support.lemonsim\" target=\"_blank\" rel=\"noopener noreferrer\">Instagram</a>, <a href=\"https://www.youtube.com/@Lemonsim-i9t\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a> and <a href=\"https://x.com/Lemonsimc\" target=\"_blank\" rel=\"noopener noreferrer\">X</a>.",
    "ab.w.cta": "Talk to our team",
    "ft.tag": "Prepaid eSIMs and SIM cards for travelers.",
    "tr.stripe": "Checkout powered by Stripe",
    "tr.support": "24/7 email support",
    "tr.check": "Check compatibility",
    "tr.refund": "Refund policy",
    "pd.buy2.esim": "Please check your phone before buying: no change-of-mind refunds, except where required by law.",
    "pd.buy2.sim": "Delivery usually takes 5–7 days. Please check your phone before buying: no change-of-mind refunds, except where required by law.",
    "cp.nav": "Device compatibility",
    "cp.crumb": "Compatible phones",
    "cp.h1": "Is your phone eSIM compatible?",
    "cp.intro": "Search our list of eSIM phones, or check your own phone in a minute. Planning to use a physical SIM card instead? That's covered below too.",
    "cp.j.search": "Search models",
    "cp.j.settings": "Check in Settings",
    "cp.j.unlock": "Carrier-unlocked?",
    "cp.j.sim": "Using a SIM card",
    "cp.j.list": "All listed models",
    "cp.tool.h2": "Search your phone model",
    "cp.reset": "Clear search",
    "cp.list.p": "Open a brand to see its models. The note under each brand explains regional versions without eSIM.",
    "cp.models": "{n} models",
    "cp.set.p": "The quickest way to be sure is to look on the phone itself.",
    "cp.sim.h2": "Using a LemonSIM physical SIM card",
    "cp.sim.bands": "Your phone should also support the 4G bands used at your destination. You'll find them in your phone's specifications.",
    "cp.faq": "Common questions",
    "cp.q1": "My phone isn't on the list. Can I still use an eSIM?",
    "cp.a1": "Possibly. Our list isn't complete. Dial *#06# or look in Settings: if you see an EID or an \"Add eSIM\" option, your phone has eSIM.",
    "cp.q2": "Why does it matter where I bought my phone?",
    "cp.a2": "Some models are sold without eSIM in certain countries. The note under each brand in the list tells you which versions to watch for.",
    "cp.q3": "How do I know if my phone is carrier-unlocked?",
    "cp.a3": "Phones bought outright from the manufacturer or a retailer are usually unlocked. If yours came with a carrier contract, ask your carrier. On iPhone, Settings › General › About › Carrier Lock should say \"No SIM restrictions\".",
    "cp.q4": "What if my phone doesn't support eSIM?",
    "cp.a4": "A <a href=\"sim-card.html\">LemonSIM physical SIM card</a> works in any unlocked phone with a free SIM slot. It's delivered to your address, so order it a week or so before you travel.",
    "cp.guide": "Full compatibility guide",
