    "dc.r.nodays": "No single plan covers {n} days. Plans last up to {max} days, and an eSIM plan can't be topped up.",
    "dc.r.nodata": "No single plan has {gb} for this trip length.",
    "dc.r.unl": "{country} has Unlimited plans only, so this is the cheapest one that lasts your whole trip.",
    "dc.r.unlalso": "{country} also has Unlimited plans. Check their details on the plans page.",
