    "dc.r.other": "Choose a destination above to see a matching plan, or <a href=\"esim.html\">browse all eSIM destinations</a>.",
    "dc.reset": "Reset",
    "dc.notice.ver": "This calculator version isn't supported, so the default settings are shown.",
    "dc.notice.bad": "Some settings in the link couldn't be read, so defaults are used for them.",
    "dc.noscript": "The result shown is for the default settings (USA, 7 days, Typical). Changing the inputs needs JavaScript.",
    "dc.usage.p": "These are the rates the calculator uses. Real use depends on the app, its settings and the network, so treat them as planning numbers.",
    "dc.th.act": "Activity",
    "dc.th.use": "Estimated data use",
    "dc.th.basis": "Basis",
    "dc.basis.est": "LemonSIM estimate",
    "dc.m.h3": "How the estimate works",
    "dc.m.p1": "For each activity we multiply your daily amount by a low and a high rate, add the activities up and multiply by the number of days. That gives the range. \"Plan for\" takes the high end, adds 15% and rounds up to the next 0.5 GB. The range shows different scenarios; it isn't a statistical confidence interval.",
    "dc.m.p2": "Streaming uses Netflix's published figures: about 167 MB per hour with Save Data on mobile, 0.7–1 GB for standard quality and up to 3 GB for HD. Music is converted from Spotify's bitrates (96–320 kbit/s, lossless not included). Video calls are converted from Zoom's recommended bandwidth for 1:1 calls, counting upload and download; other apps differ. Everything else is a LemonSIM estimate.",
    "dc.m.p3": "Not included: app and system updates, cloud photo backup and large downloads. Do those on Wi-Fi or add time for them. Hotspot doesn't change the rates: a laptop or tablet on your hotspot uses data for whatever it does, so add its activities to the totals.",
    "dc.m.p4": "Units are decimal: 1 GB = 1,000 MB. Calculator version 1, rates last updated November 2026.",
    "dc.ex1.t": "Weekend city break",
    "dc.ex1.d": "3 days, Light use",
    "dc.ex2.t": "Two weeks in Japan",
    "dc.ex2.d": "14 days, Typical use",
    "dc.ex3.t": "A month of remote work",
    "dc.ex3.d": "30 days, Typical use plus 3 hours of laptop work and 1 hour of video calls a day",
    "dc.ex.load": "Load this example",
    "dc.save.1": "Download offline maps for the city before you leave.",
    "dc.save.2": "Turn off video autoplay in social apps.",
    "dc.save.3": "Download shows and playlists on Wi-Fi instead of streaming them.",
    "dc.save.4": "Pause cloud photo backup and app updates until you are on Wi-Fi.",
    "dc.save.5": "Turn on Low Data Mode (iPhone) or Data Saver (Android) for the travel line.",
    "dc.save.more": "Step-by-step settings: <a href=\"https://www.lemonsim.com/blog/esim-data-saving-settings-iphone-android\">how to save eSIM data on iPhone and Android</a>.",
    "dc.q1": "Is 1 GB a day enough?",
    "dc.a1": "For maps, messages, social media and some short videos, usually yes. Streaming video, long video calls or working on a laptop can use several GB a day. Use the calculator with your own hours to check.",
    "dc.q2": "Does hotspot use more data?",
    "dc.a2": "Hotspot itself doesn't, but the devices on it do. Laptops often sync files and install updates in the background, so add their activities to your estimate. Hotspot works on every LemonSIM plan.",
    "dc.q3": "What happens if I run out of data?",
    "dc.a3": "An eSIM plan can't be topped up, so buy another eSIM plan for the rest of your trip. A LemonSIM physical SIM card can be topped up at <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a>.",
    "dc.q4": "Why does the calculator suggest a plan bigger than my estimate?",
    "dc.a4": "It plans for the high end of the range plus 15%, then picks the cheapest plan that has at least that much data and lasts your whole trip. Plans come in fixed sizes, so the cheapest one that fits can be well above your estimate.",
    "dc.cta.q": "Not sure how much data you need?",
    "dc.cta.a": "Estimate it",
