    "ab.eyebrow": "关于 LemonSIM",
    "ab.h1": "走得更远，一路在线。",
    "ab.sub": "LemonSIM 为出境旅行者提供实用的 eSIM 和 SIM 卡套餐，到哪里都能上网。",
