    "ab.chip3": "24 小时客服",
    "ab.t1": "出境上网，不再麻烦",
    "ab.t2": "LemonSIM 是为出门在外、需要稳定流量的人提供的旅行上网服务。我们把各个目的地的 eSIM 和实体 SIM 卡集中在一起，选择起来一目了然。",
    "ab.t3": "我们的目标很简单：帮助旅行者选对套餐、弄懂用法，在出发前或旅途中放心上网。",
    "ab.t4": "我们的使命",
    "ab.t5": "让上网成为旅行中自然而然的一部分",
