    "ab.f1p": "从美国、日本到欧洲、摩洛哥，每个目的地都有专属套餐。",
    "ab.f2t": "SIM 卡地区",
    "ab.f2p": "美国、欧洲、日本的实体 SIM 卡，约 5–7 天送达。",
    "ab.f3n": "预付费",
    "ab.f3t": "无合约",
    "ab.f3p": "按需要选择流量和天数，没有长期合约。",
    "ab.f4t": "邮件客服",
    "ab.f4p": "出发前或旅途中，随时发邮件到 info@lemonsim.com。",
    "ab.t11": "带来的改变",
    "ab.t12": "少花时间折腾上网，多花时间享受旅行。",
    "ab.t13": "我们专注于旅行者最在意的那些时刻。",
    "ab.t14": "落地即用",
    "ab.t15": "提前准备好，旅程一开始就能用地图、收消息、查预订和交通信息。",
    "ab.t16": "费用更可预期",
    "ab.t17": "对比预付费套餐的流量、天数和价格，一清二楚。",
    "ab.t18": "选择更简单",
    "ab.t19": "直接找到目的地对应的套餐，不用在无关套餐里翻找。",
    "ab.t20": "我们的理念",
    "ab.t21": "我们怎么做",
    "ab.t22": "清楚第一",
    "ab.t23": "我们用简单的话讲清楚套餐、价格和设置，让旅行者做出明智的选择。",
    "ab.t24": "实用为本",
    "ab.t25": "每个环节都应该解决真实的旅行需求，并且简单好用。",
    "ab.t26": "可靠的支持",
    "ab.t27": "人在异乡时最需要网络，所以指导和支持必须实用。",
    "ab.t28": "旅行无界",
    "ab.t29": "我们相信，保持联系能让人们更自由、更有信心地出行。",
    "ab.t30": "我们的团队",
    "ab.t31": "由懂旅行上网的人打造",
    "ab.t32": "LemonSIM 汇集了旅行通信、数字产品、内容和客户服务方面的经验。我们跨领域合作，只有一个共同标准：让旅行者的每一步都更清楚。",
    "ab.t33": "联系我们的团队",
    "co.h1": "我们能帮你什么？",
    "co.sub": "随时发邮件给我们，客服 24 小时在线。",
    "co.t1": "找到合适的帮助",
    "co.t2": "你需要什么帮助？",
    "co.t3": "选择套餐",
    "co.t4": "出发前对比各目的地的套餐、流量和天数。",
    "co.t5": "浏览 eSIM 套餐",
    "co.t6": "浏览 SIM 卡",
    "co.t7": "设置和故障排查",
    "co.t8": "安装、激活、流量设置、APN 或连接问题的帮助。",
    "co.t9": "前往支持页面",
    "co.t10": "快速解答",
    "co.t11": "查看兼容性、热点、激活和旅行流量的常见问题。",
    "co.t12": "查看常见问题",
    "co.t13": "接下来会怎样",
    "co.t14": "专注解决你的问题",
    "co.t15": "我们查看你的请求",
    "co.t16": "我们确认产品、目的地、设备，以及需要帮助的环节。",
    "co.t17": "我们确认细节",
    "co.t18": "如果缺少信息，我们只会询问继续处理所需的内容。",
    "co.t19": "我们指导下一步",
    "co.t20": "你会收到实用的操作说明，或最合适的解决方法。",
    "co.t21": "已经在旅途中？",
    "co.t22": "先做几项快速检查",
    "co.t23": "确认 LemonSIM 线路已打开、被选为上网线路，并且打开了数据漫游，然后重启设备。还是连不上？准备好手机型号和套餐信息，前往支持页面。",
    "co.t24": "获取设置帮助",
    "su.t1": "找到合适的设置指南，检查常见的网络设置，并准备好客服需要的信息。",
    "su.t2": "从这里开始",
    "su.t3": "如果无法上网",
    "su.t4": "准备好你的求助信息",
    "su.t5": "更多解答",
    "su.t6": "选择与你的 LemonSIM 产品对应的指南。eSIM 请在需要用流量前不久连着 Wi-Fi 安装：套餐从安装时开始计算。",
    "su.t7": "如何设置 eSIM",
    "su.t8": "如何使用 SIM 卡",
    "su.t9": "求助前请先检查这些设置：",
    "su.t10": "确认 LemonSIM 线路已打开，并被选为上网线路。",
    "su.t11": "为 LemonSIM 线路打开数据漫游。",
    "su.t12": "打开飞行模式 30 秒，然后关闭。",
    "su.t13": "重启设备，等几分钟让它注册到网络。",
    "su.t14": "检查 APN：eSIM 通常会自动设置；LemonSIM 实体卡请按说明中的 APN 设置。",
    "su.t15": "请附上目的地、eSIM 还是 SIM 卡、手机型号、套餐名称，以及问题的简短描述。如果有错误提示，请附上原文。",
    "su.t16": "不要公开或发送密码、完整的支付信息或 eSIM 激活码。",
    "su.t17": "关于兼容性、热点、激活和旅行流量的问题，请查看常见问题。",
    "su.t18": "查看常见问题",
    "su.t19": "联系 LemonSIM",
