    "rv.line": "由 LemonSIM 客服团队审核 · 2026 年 11 月 3 日 · <a href=\"editorial-policy.html\">编辑准则</a>",
    "ed.h1": "编辑准则",
    "ed.intro": "我们如何撰写、核对和更正本网站上的信息。",
    "ed.s1": "谁负责",
    "ed.s1.p": "LemonSIM 的客服和内容团队负责网站上的购买信息和旅行上网指南。",
    "ed.s2": "我们如何核对信息",
    "ed.s2.p": "发布或审核指南之前，我们会核对相关的手机厂商资料、运营商或合作网络信息，以及 LemonSIM 的套餐信息。如果来源能帮你核实某项说法，我们会附上链接。我们的<a href=\"esim-compatible-phones.html\" data-compat=\"esim\">兼容机型列表</a>只是参考，不能保证适用于每个地区版本的手机。",
    "ed.s3": "审核与日期",
    "ed.s3.p": "\"审核\"日期表示我们的团队在那一天核对过页面上的事实信息和相关来源。审核后也可能不需要修改。只有完成审核，我们才会更新审核日期。",
    "ed.s4": "更正",
    "ed.s4.p": "如果发现错误，请发邮件到 <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>，附上页面链接和你认为有误的内容。我们会调查并更正确认的错误。重新审核整页后，我们会更新审核日期。",
    "ed.s5": "商业透明",
    "ed.s5.p": "LemonSIM 销售本网站介绍的套餐。我们的指南介绍自己的产品和使用要求。任何赞助内容或付费推广都会清楚标注。",
    "ab.w.eyebrow": "与我们合作",
    "ab.w.h2": "你可以从 LemonSIM 得到什么",
    "ab.w1t": "我们卖什么",
    "ab.w1p": "13 个目的地的 eSIM 套餐，以及美国、欧洲和日本的 SIM 卡。每个套餐页都写明流量、有效期、价格和合作网络。",
    "ab.w2t": "需要时随时帮忙",
    "ab.w2p": "出发前和旅途中，都可以随时发邮件到 <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>，邮件客服 24 小时在线。",
    "ab.w3t": "清楚的政策",
    "ab.w3p": "购买前可以阅读我们的<a href=\"refund-policy.html\">退款政策</a>、<a href=\"terms-of-service.html\">服务条款</a>、<a href=\"privacy-policy.html\">隐私政策</a>和<a href=\"editorial-policy.html\">编辑准则</a>。",
    "ab.w4t": "安全支付",
    "ab.w4p": "结账由 Stripe 提供，你的完整卡号由 Stripe 处理，我们看不到。",
    "ab.w5t": "关注我们",
    "ab.w5p": "在 <a href=\"https://www.facebook.com/share/1DepLp294g/?mibextid=wwXIfr\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a>、<a href=\"https://instagram.com/support.lemonsim\" target=\"_blank\" rel=\"noopener noreferrer\">Instagram</a>、<a href=\"https://www.youtube.com/@Lemonsim-i9t\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a> 和 <a href=\"https://x.com/Lemonsimc\" target=\"_blank\" rel=\"noopener noreferrer\">X</a> 关注 LemonSIM。",
    "ab.w.cta": "联系我们的团队",
    "ft.tag": "面向旅行者的预付 eSIM 和 SIM 卡。",
