    "cp.h1": "你的手机支持 eSIM 吗？",
    "cp.intro": "在我们的 eSIM 机型列表里搜索，或者花一分钟直接在手机上检查。打算用实体 SIM 卡？下面也有说明。",
    "cp.j.search": "搜索机型",
