    "cp.reset": "清除搜索",
    "cp.list.p": "展开品牌即可查看机型。品牌下方的说明会告诉你哪些地区版本不支持 eSIM。",
    "cp.models": "{n} 个机型",
    "cp.set.p": "最可靠的方法是直接在手机上查看。",
    "cp.sim.h2": "使用 LemonSIM 实体 SIM 卡",
    "cp.sim.bands": "手机还需要支持目的地使用的 4G 频段，可以在手机的规格参数里查到。",
    "cp.faq": "常见问题",
    "cp.q1": "我的手机不在列表里，还能用 eSIM 吗？",
    "cp.a1": "有可能。我们的列表并不完整。拨打 *#06# 或在设置里查看：如果能看到 EID 或\"添加 eSIM\"选项，就说明手机支持 eSIM。",
    "cp.q2": "为什么手机在哪里买的会有影响？",
    "cp.a2": "有些机型在部分国家或地区销售的版本没有 eSIM。列表中每个品牌下方的说明会告诉你需要注意哪些版本。",
    "cp.q3": "怎么知道手机有没有被运营商锁定？",
    "cp.a3": "直接从品牌官方或零售商全款购买的手机通常没有锁。如果是随运营商合约购买的，请咨询运营商。iPhone 可以在 设置 › 通用 › 关于本机 › 运营商锁 查看，显示\"无 SIM 卡限制\"即可。",
    "cp.q4": "如果手机不支持 eSIM 怎么办？",
    "cp.a4": "<a href=\"sim-card.html\">LemonSIM 实体 SIM 卡</a>适用于任何未锁、有空闲卡槽的手机。它会寄到你的地址，建议出发前一周左右下单。",
    "cp.guide": "完整兼容性指南",
