    "dc.r.nodays": "没有单个套餐能覆盖 {n} 天。套餐最长 {max} 天，eSIM 套餐不能充值续期。",
    "dc.r.nodata": "没有单个套餐能在这个天数内提供 {gb}。",
    "dc.r.unl": "{country}只提供不限量套餐，这是能覆盖整个行程的最便宜的一个。",
    "dc.r.unlalso": "{country}也有不限量套餐，可以在套餐页面查看详情。",
    "dc.r.all": "查看{country}全部套餐",
    "dc.r.other": "在上方选择目的地即可看到匹配的套餐，或<a href=\"esim.html\">浏览全部 eSIM 目的地</a>。",
    "dc.reset": "重置",
    "dc.notice.ver": "不支持这个计算器版本，已显示默认设置。",
    "dc.notice.bad": "链接里有些设置无法读取，已改用默认值。",
    "dc.noscript": "这里显示的是默认设置（美国，7 天，一般）的结果。修改输入需要启用 JavaScript。",
    "dc.usage.p": "这是计算器使用的数值。实际用量取决于 App、设置和网络，请把它们当作规划参考。",
    "dc.th.act": "活动",
    "dc.th.use": "预计用量",
    "dc.th.basis": "依据",
    "dc.basis.est": "LemonSIM 估算",
    "dc.m.h3": "估算方法",
    "dc.m.p1": "每项活动用每日用量分别乘以低值和高值，加总后再乘以天数，就得到区间。\"建议准备\"取区间上限，加 15% 余量，再向上取整到 0.5 GB。这个区间代表不同使用情形，不是统计意义上的置信区间。",
    "dc.m.p2": "视频按 Netflix 公布的数字：手机\"省流量\"模式约每小时 167 MB，标清 0.7–1 GB，高清最多 3 GB。音乐按 Spotify 的码率换算（96–320 kbit/s，不含无损）。视频通话按 Zoom 一对一通话的建议带宽换算，上下行都算在内；其他 App 会有差异。其余各项为 LemonSIM 的估算。",
    "dc.m.p3": "不包括：App 和系统更新、照片云备份、大文件下载。这些最好连 Wi-Fi 进行，或者另外加上相应时间。开热点不会改变这些数值：连到热点的电脑或平板做什么就用多少流量，把它的活动一起算进去即可。",
    "dc.m.p4": "单位按十进制：1 GB = 1,000 MB。计算器第 1 版，数值更新于 2026 年 11 月。",
    "dc.ex1.t": "周末城市游",
    "dc.ex1.d": "3 天，轻度使用",
    "dc.ex2.t": "日本两周游",
    "dc.ex2.d": "14 天，一般使用",
    "dc.ex3.t": "远程办公一个月",
    "dc.ex3.d": "30 天，一般使用，另加每天 3 小时笔记本电脑办公和 1 小时视频通话",
    "dc.ex.load": "载入这个示例",
    "dc.save.1": "出发前下载城市离线地图。",
    "dc.save.2": "关闭社交 App 里的视频自动播放。",
    "dc.save.3": "用 Wi-Fi 提前下载剧集和歌单，不要在路上在线播放。",
    "dc.save.4": "暂停照片云备份和 App 更新，等连上 Wi-Fi 再进行。",
    "dc.save.5": "为旅行用的号码打开\"低数据模式\"（iPhone）或\"流量节省程序\"（Android）。",
    "dc.save.more": "详细设置步骤：<a href=\"https://www.lemonsim.com/blog/esim-data-saving-settings-iphone-android\">如何在 iPhone 和 Android 上节省 eSIM 流量</a>（英文）。",
    "dc.q1": "每天 1 GB 够用吗？",
    "dc.a1": "如果只是地图、聊天、社交媒体和少量短视频，通常够用。看视频、长时间视频通话或用电脑办公，每天可能会用掉好几 GB。用计算器按你自己的使用时间算一下。",
    "dc.q2": "开热点会更费流量吗？",
    "dc.a2": "热点本身不费流量，但连上来的设备会用流量。电脑经常在后台同步文件、安装更新，所以要把它的活动算进估算里。所有 LemonSIM 套餐都可以开热点。",
    "dc.q3": "流量用完了怎么办？",
    "dc.a3": "eSIM 套餐不能充值，需要为剩下的行程再买一个 eSIM 套餐。LemonSIM 实体 SIM 卡可以在 <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a> 充值。",
    "dc.q4": "为什么推荐的套餐比估算的流量大？",
    "dc.a4": "它按区间上限再加 15% 来准备，然后挑一个流量够、天数也覆盖整个行程的最便宜套餐。套餐是固定档位，所以够用的最便宜套餐可能比估算大不少。",
    "dc.cta.q": "不确定需要多少流量？",
    "dc.cta.a": "估算一下",
