    "ab.eyebrow": "關於 LemonSIM",
    "ab.h1": "走得更遠，一路在線。",
    "ab.sub": "LemonSIM 為出國旅客提供實用的 eSIM 和 SIM 卡方案，到哪裡都能上網。",
    "ab.chip1": "13 個 eSIM 目的地",
    "ab.chip2": "3 個 SIM 卡地區",
    "ab.chip3": "24 小時客服",
    "ab.t1": "出國上網，不再麻煩",
    "ab.t2": "LemonSIM 是為出門在外、需要穩定數據的人提供的旅行上網服務。我們把各個目的地的 eSIM 和實體 SIM 卡集中在一起，選擇起來一目了然。",
    "ab.t3": "我們的目標很簡單：幫助旅客選對方案、弄懂用法，在出發前或旅途中安心上網。",
    "ab.t4": "我們的使命",
    "ab.t5": "讓上網成為旅行中自然而然的一部分",
    "ab.t6": "我們提供清楚的方案資訊、簡單的設定指南和全程實用的支援，讓旅行上網不再有不確定。",
    "ab.t7": "選擇清楚，支援實用，旅途更順暢。",
    "ab.t8": "一覽",
    "ab.t9": "LemonSIM 一覽",
    "ab.t10": "依目的地、裝置和行程長短，彈性選擇上網方式。",
    "ab.f1t": "eSIM 目的地",
    "ab.f1p": "從美國、日本到歐洲、摩洛哥，每個目的地都有專屬方案。",
    "ab.f2t": "SIM 卡地區",
    "ab.f2p": "美國、歐洲、日本的實體 SIM 卡，約 5–7 天送達。",
    "ab.f3n": "預付",
    "ab.f3t": "無合約",
    "ab.f3p": "依需要選擇數據和天數，沒有長期合約。",
    "ab.f4t": "郵件客服",
    "ab.f4p": "出發前或旅途中，隨時寄信到 info@lemonsim.com。",
    "ab.t11": "帶來的改變",
    "ab.t12": "少花時間處理上網，多花時間享受旅行。",
    "ab.t13": "我們專注於旅客最在意的那些時刻。",
    "ab.t14": "落地即用",
    "ab.t15": "提前準備好，旅程一開始就能用地圖、收訊息、查預訂和交通資訊。",
    "ab.t16": "費用更可預期",
    "ab.t17": "比較預付方案的數據、天數和價格，一清二楚。",
    "ab.t18": "選擇更簡單",
    "ab.t19": "直接找到目的地對應的方案，不用在無關方案中翻找。",
    "ab.t20": "我們的理念",
    "ab.t21": "我們怎麼做",
    "ab.t22": "清楚第一",
    "ab.t23": "我們用簡單的話講清楚方案、價格和設定，讓旅客做出明智的選擇。",
    "ab.t24": "實用為本",
    "ab.t25": "每個環節都應該解決真實的旅行需求，並且簡單好用。",
    "ab.t26": "可靠的支援",
    "ab.t27": "人在異鄉時最需要網路，所以指導和支援必須實用。",
    "ab.t28": "旅行無界",
    "ab.t29": "我們相信，保持聯繫能讓人們更自由、更有信心地出行。",
    "ab.t30": "我們的團隊",
    "ab.t31": "由懂旅行上網的人打造",
    "ab.t32": "LemonSIM 匯集了旅行通訊、數位產品、內容和客戶服務方面的經驗。我們跨領域合作，只有一個共同標準：讓旅客的每一步都更清楚。",
    "ab.t33": "聯絡我們的團隊",
    "co.h1": "我們能幫你什麼？",
    "co.sub": "隨時寄信給我們，客服 24 小時服務。",
    "co.t1": "找到合適的協助",
    "co.t2": "你需要什麼協助？",
    "co.t3": "選擇方案",
    "co.t4": "出發前比較各目的地的方案、數據和天數。",
    "co.t5": "瀏覽 eSIM 方案",
    "co.t6": "瀏覽 SIM 卡",
    "co.t7": "設定與故障排除",
    "co.t8": "安裝、啟用、數據設定、APN 或連線問題的協助。",
    "co.t9": "前往支援頁面",
    "co.t10": "快速解答",
    "co.t11": "查看相容性、熱點、啟用和旅行數據的常見問題。",
    "co.t12": "查看常見問題",
    "co.t13": "接下來會怎樣",
    "co.t14": "專注解決你的問題",
    "co.t15": "我們查看你的請求",
    "co.t16": "我們確認產品、目的地、裝置，以及需要協助的環節。",
    "co.t17": "我們確認細節",
    "co.t18": "如果缺少資訊，我們只會詢問繼續處理所需的內容。",
    "co.t19": "我們指導下一步",
    "co.t20": "你會收到實用的操作說明，或最合適的解決方法。",
    "co.t21": "已經在旅途中？",
    "co.t22": "先做幾項快速檢查",
    "co.t23": "確認 LemonSIM 線路已開啟、被選為上網線路，並且開啟了數據漫遊，然後重新啟動裝置。還是連不上？準備好手機型號和方案資訊，前往支援頁面。",
    "co.t24": "取得設定協助",
    "su.t1": "找到合適的設定指南，檢查常見的網路設定，並準備好客服需要的資訊。",
    "su.t2": "從這裡開始",
    "su.t3": "如果無法上網",
    "su.t4": "準備好你的求助資訊",
    "su.t5": "更多解答",
    "su.t6": "選擇與你的 LemonSIM 產品對應的指南。eSIM 請在需要使用數據前不久連著 Wi-Fi 安裝：方案從安裝時開始計算。",
    "su.t7": "如何設定 eSIM",
    "su.t8": "如何使用 SIM 卡",
    "su.t9": "求助前請先檢查這些設定：",
    "su.t10": "確認 LemonSIM 線路已開啟，並被選為上網線路。",
    "su.t11": "為 LemonSIM 線路開啟數據漫遊。",
    "su.t12": "開啟飛航模式 30 秒，然後關閉。",
    "su.t13": "重新啟動裝置，等幾分鐘讓它註冊到網路。",
    "su.t14": "檢查 APN：eSIM 通常會自動設定；LemonSIM 實體卡請依說明中的 APN 設定。",
    "su.t15": "請附上目的地、eSIM 還是 SIM 卡、手機型號、方案名稱，以及問題的簡短描述。如果有錯誤訊息，請附上原文。",
    "su.t16": "不要公開或傳送密碼、完整的付款資訊或 eSIM 啟用碼。",
    "su.t17": "關於相容性、熱點、啟用和旅行數據的問題，請查看常見問題。",
    "su.t18": "查看常見問題",
