    "ed.h1": "編輯準則",
    "ed.intro": "我們如何撰寫、核對和更正本網站上的資訊。",
    "ed.s1": "誰負責",
    "ed.s1.p": "LemonSIM 的客服與內容團隊負責網站上的購買資訊和旅行上網指南。",
    "ed.s2": "我們如何核對資訊",
    "ed.s2.p": "發布或審核指南之前，我們會核對相關的手機廠商資料、電信商或合作網路資訊，以及 LemonSIM 的方案資訊。如果來源能幫你核實某項說法，我們會附上連結。我們的<a href=\"esim-compatible-phones.html\" data-compat=\"esim\">相容機型列表</a>只是參考，不能保證適用於每個地區版本的手機。",
    "ed.s3": "審核與日期",
    "ed.s3.p": "「審核」日期表示我們的團隊在那一天核對過頁面上的事實資訊和相關來源。審核後也可能不需要修改。只有完成審核，我們才會更新審核日期。",
    "ed.s4": "更正",
    "ed.s4.p": "如果發現錯誤，請寄信到 <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>，附上頁面連結和你認為有誤的內容。我們會調查並更正確認的錯誤。重新審核整頁後，我們會更新審核日期。",
    "ed.s5": "商業透明",
    "ed.s5.p": "LemonSIM 銷售本網站介紹的方案。我們的指南介紹自己的產品和使用要求。任何贊助內容或付費推廣都會清楚標示。",
    "ab.w.eyebrow": "與我們合作",
    "ab.w.h2": "你可以從 LemonSIM 得到什麼",
    "ab.w1t": "我們賣什麼",
    "ab.w1p": "13 個目的地的 eSIM 方案，以及美國、歐洲和日本的 SIM 卡。每個方案頁都寫明流量、有效期、價格和合作網路。",
    "ab.w2t": "需要時隨時幫忙",
    "ab.w2p": "出發前和旅途中，都可以隨時寄信到 <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>，郵件客服 24 小時在線。",
    "ab.w3t": "清楚的政策",
    "ab.w3p": "購買前可以閱讀我們的<a href=\"refund-policy.html\">退款政策</a>、<a href=\"terms-of-service.html\">服務條款</a>、<a href=\"privacy-policy.html\">隱私政策</a>和<a href=\"editorial-policy.html\">編輯準則</a>。",
    "ab.w4t": "安全支付",
    "ab.w4p": "結帳由 Stripe 提供，你的完整卡號由 Stripe 處理，我們看不到。",
    "ab.w5t": "關注我們",
    "ab.w5p": "在 <a href=\"https://www.facebook.com/share/1DepLp294g/?mibextid=wwXIfr\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a>、<a href=\"https://instagram.com/support.lemonsim\" target=\"_blank\" rel=\"noopener noreferrer\">Instagram</a>、<a href=\"https://www.youtube.com/@Lemonsim-i9t\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a> 和 <a href=\"https://x.com/Lemonsimc\" target=\"_blank\" rel=\"noopener noreferrer\">X</a> 關注 LemonSIM。",
    "ab.w.cta": "聯絡我們的團隊",
    "ft.tag": "為旅客提供的預付 eSIM 和 SIM 卡。",
    "tr.stripe": "由 Stripe 提供安全結帳",
    "tr.support": "24 小時郵件客服",
    "tr.check": "檢查相容性",
    "tr.refund": "退款政策",
    "pd.buy2.esim": "購買前請先檢查手機：除法律另有規定外，不提供因個人原因的退款。",
    "pd.buy2.sim": "配送通常需要 5–7 天。購買前請先檢查手機：除法律另有規定外，不提供因個人原因的退款。",
    "cp.nav": "裝置相容性",
    "cp.crumb": "相容機型",
    "cp.h1": "你的手機支援 eSIM 嗎？",
    "cp.intro": "在我們的 eSIM 機型列表中搜尋，或花一分鐘直接在手機上檢查。打算使用實體 SIM 卡？下方也有說明。",
    "cp.j.search": "搜尋機型",
    "cp.j.settings": "在設定中查看",
    "cp.j.unlock": "是否被電信公司鎖定？",
    "cp.j.sim": "使用實體 SIM 卡",
    "cp.j.list": "全部機型",
    "cp.tool.h2": "搜尋你的手機型號",
    "cp.reset": "清除搜尋",
    "cp.list.p": "展開品牌即可查看機型。品牌下方的說明會告訴你哪些地區版本不支援 eSIM。",
    "cp.models": "{n} 個機型",
    "cp.set.p": "最可靠的方法是直接在手機上查看。",
    "cp.sim.h2": "使用 LemonSIM 實體 SIM 卡",
    "cp.sim.bands": "手機還需要支援目的地使用的 4G 頻段，可在手機的規格中查到。",
    "cp.faq": "常見問題",
    "cp.q1": "我的手機不在列表中，還能用 eSIM 嗎？",
    "cp.a1": "有可能。我們的列表並不完整。撥打 *#06# 或在設定中查看：如果看到 EID 或「新增 eSIM」選項，就表示手機支援 eSIM。",
    "cp.q2": "為什麼手機在哪裡買的會有影響？",
    "cp.a2": "有些機型在部分國家或地區銷售的版本沒有 eSIM。列表中每個品牌下方的說明會告訴你需要留意哪些版本。",
    "cp.q3": "怎麼知道手機有沒有被電信公司鎖定？",
    "cp.a3": "直接向品牌官方或零售商全額購買的手機通常沒有鎖。如果是搭配電信合約購買的，請洽詢電信公司。iPhone 可在 設定 › 一般 › 關於本機 › 電信業者鎖定 查看，顯示「無 SIM 卡限制」即可。",
    "cp.q4": "如果手機不支援 eSIM 怎麼辦？",
    "cp.a4": "<a href=\"sim-card.html\">LemonSIM 實體 SIM 卡</a>適用於任何未鎖、有空卡槽的手機。它會寄到你的地址，建議出發前一週左右下單。",
    "cp.guide": "完整相容性指南",
