    "dc.r.other": "在上方選擇目的地即可看到相符的方案，或<a href=\"esim.html\">瀏覽全部 eSIM 目的地</a>。",
    "dc.reset": "重設",
    "dc.notice.ver": "不支援這個計算器版本，已顯示預設設定。",
    "dc.notice.bad": "連結中有些設定無法讀取，已改用預設值。",
    "dc.noscript": "這裡顯示的是預設設定（美國，7 天，一般）的結果。修改輸入需要啟用 JavaScript。",
    "dc.usage.p": "這是計算器使用的數值。實際用量取決於 App、設定和網路，請把它們當作規劃參考。",
    "dc.th.act": "活動",
    "dc.th.use": "預估用量",
    "dc.th.basis": "依據",
    "dc.basis.est": "LemonSIM 估算",
    "dc.m.h3": "估算方式",
    "dc.m.p1": "每項活動以每日用量分別乘以低值和高值，加總後再乘以天數，就得到區間。「建議準備」取區間上限，加 15% 餘量，再無條件進位到 0.5 GB。這個區間代表不同使用情境，不是統計上的信賴區間。",
    "dc.m.p2": "影片依 Netflix 公布的數字：手機「節省數據」模式約每小時 167 MB，標準畫質 0.7–1 GB，高畫質最多 3 GB。音樂依 Spotify 的位元率換算（96–320 kbit/s，不含無損）。視訊通話依 Zoom 一對一通話的建議頻寬換算，上下行都計入；其他 App 會有差異。其餘各項為 LemonSIM 的估算。",
    "dc.m.p3": "不包括：App 和系統更新、照片雲端備份、大型檔案下載。這些最好連 Wi-Fi 進行，或另外加上相應時間。開熱點不會改變這些數值：連到熱點的筆電或平板做什麼就用多少流量，把它的活動一起算進去即可。",
    "dc.m.p4": "單位以十進位計：1 GB = 1,000 MB。計算器第 1 版，數值更新於 2026 年 11 月。",
    "dc.ex1.t": "週末城市遊",
    "dc.ex1.d": "3 天，輕度使用",
    "dc.ex2.t": "日本兩週遊",
    "dc.ex2.d": "14 天，一般使用",
    "dc.ex3.t": "遠端工作一個月",
    "dc.ex3.d": "30 天，一般使用，另加每天 3 小時筆電工作和 1 小時視訊通話",
    "dc.ex.load": "載入這個範例",
    "dc.save.1": "出發前下載城市離線地圖。",
    "dc.save.2": "關閉社群 App 中的影片自動播放。",
    "dc.save.3": "用 Wi-Fi 先下載劇集和歌單，不要在路上線上播放。",
    "dc.save.4": "暫停照片雲端備份和 App 更新，等連上 Wi-Fi 再進行。",
    "dc.save.5": "為旅行用的門號開啟「低數據模式」（iPhone）或「數據節省模式」（Android）。",
    "dc.save.more": "詳細設定步驟：<a href=\"https://www.lemonsim.com/blog/esim-data-saving-settings-iphone-android\">如何在 iPhone 和 Android 上節省 eSIM 流量</a>（英文）。",
    "dc.q1": "每天 1 GB 夠用嗎？",
    "dc.a1": "如果只是地圖、聊天、社群媒體和少量短影音，通常夠用。看影片、長時間視訊通話或用筆電工作，每天可能會用掉好幾 GB。用計算器依你自己的使用時間算一下。",
    "dc.q2": "開熱點會更耗流量嗎？",
    "dc.a2": "熱點本身不耗流量，但連上來的裝置會用流量。筆電常在背景同步檔案、安裝更新，所以要把它的活動算進估算。所有 LemonSIM 方案都能開熱點。",
    "dc.q3": "流量用完了怎麼辦？",
    "dc.a3": "eSIM 方案無法加值，需要為剩下的行程再買一個 eSIM 方案。LemonSIM 實體 SIM 卡可在 <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a> 加值。",
    "dc.q4": "為什麼推薦的方案比估算的流量大？",
    "dc.a4": "它以區間上限再加 15% 來準備，然後挑一個流量夠、天數也涵蓋整個行程的最便宜方案。方案是固定級距，所以夠用的最便宜方案可能比估算大不少。",
    "dc.cta.q": "不確定需要多少流量？",
    "dc.cta.a": "估算一下",
