    "hero.search": "渡航先を検索",
    "hero.btn": "検索",
    "hero.title": "{anywhere}、つながる。",
    "hero.places": "ニューヨークでも|パリでも|ドバイでも|イスタンブールでも|バンコクでも",
    "hero.marks": "エンパイア・ステート・ビル|エッフェル塔|ブルジュ・ハリファ|スレイマニエ・モスク|ワット・アルン",
    "hero.chip": "{dest} eSIM · {price}〜",
    "hero.slide": "{place}を表示（{n}/{total}）",
    "pd.choose": "プランを選ぶ",
    "pd.tab.esim": "eSIMプラン",
    "pd.tab.sim": "SIMカードプラン",
