    "cmp.fast.note": "確認できるのはeSIM対応だけです。",
    "cmp.listnote": "リスト更新：2026年11月。地域版で異なる場合があります。",
    "rv.line": "LemonSIMサポートチームが確認 · 2026年11月3日 · <a href=\"editorial-policy.html\">編集方針</a>",
    "ed.h1": "編集方針",
    "ed.intro": "このサイトの情報をどのように書き、確認し、訂正しているかを説明します。",
    "ed.s1": "責任者",
    "ed.s1.p": "LemonSIMのサポート・コンテンツチームが、購入情報と旅行中の通信ガイドを担当しています。",
    "ed.s2": "情報の確認方法",
    "ed.s2.p": "ガイドの公開・確認の前に、メーカーの資料、通信事業者や提携ネットワークの情報、LemonSIMのプラン情報を確認します。内容を確かめるのに役立つ場合は出典へのリンクを載せます。<a href=\"esim-compatible-phones.html\" data-compat=\"esim\">対応機種リスト</a>は参考情報であり、すべての地域版モデルでの動作を保証するものではありません。",
    "ed.s3": "確認と日付",
    "ed.s3.p": "「確認」の日付は、その日にチームがページの事実情報と関連する出典を確認したことを示します。確認の結果、変更が不要な場合もあります。日付は確認を終えたときにだけ更新します。",
    "ed.s4": "訂正",
    "ed.s4.p": "誤りを見つけたら、ページのリンクと誤っていると思われる箇所を <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a> までお送りください。調査のうえ、確認できた誤りを訂正します。ページ全体を確認し直したときは、確認日を更新します。",
    "ed.s5": "商業上の透明性",
    "ed.s5.p": "LemonSIMはこのサイトで紹介しているプランを販売しています。ガイドでは自社の製品とその利用条件を説明しています。スポンサー付きの内容や有料掲載がある場合は、明確に表示します。",
    "ab.w.eyebrow": "ご利用にあたって",
    "ab.w.h2": "LemonSIMがお約束すること",
    "ab.w1t": "販売しているもの",
    "ab.w1p": "13の渡航先向けeSIMプランと、アメリカ・ヨーロッパ・日本向けのSIMカード。各プランのページにデータ量、有効期間、価格、提携ネットワークを記載しています。",
    "ab.w2t": "困ったときのサポート",
    "ab.w2p": "出発前も旅行中も、<a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a> へのメールで24時間サポートしています。",
    "ab.w3t": "わかりやすいポリシー",
    "ab.w3p": "ご購入前に<a href=\"refund-policy.html\">返金ポリシー</a>、<a href=\"terms-of-service.html\">利用規約</a>、<a href=\"privacy-policy.html\">プライバシーポリシー</a>、<a href=\"editorial-policy.html\">編集方針</a>をご覧ください。",
    "ab.w4t": "安全なお支払い",
    "ab.w4p": "決済はStripeを利用しています。カード番号はStripeが処理し、当社には届きません。",
    "ab.w5t": "フォローする",
    "ab.w5p": "<a href=\"https://www.facebook.com/share/1DepLp294g/?mibextid=wwXIfr\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a>、<a href=\"https://instagram.com/support.lemonsim\" target=\"_blank\" rel=\"noopener noreferrer\">Instagram</a>、<a href=\"https://www.youtube.com/@Lemonsim-i9t\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a>、<a href=\"https://x.com/Lemonsimc\" target=\"_blank\" rel=\"noopener noreferrer\">X</a> でLemonSIMをフォローしてください。",
    "ab.w.cta": "チームに問い合わせる",
    "ft.tag": "旅行者向けのプリペイドeSIMとSIMカード。",
    "tr.stripe": "Stripeによる安全な決済",
    "tr.support": "24時間メールサポート",
    "tr.check": "対応機種を確認",
    "tr.refund": "返金ポリシー",
    "pd.buy2.esim": "ご購入前に端末をご確認ください。法律で定められた場合を除き、お客様都合の返金はできません。",
    "pd.buy2.sim": "お届けまで通常5〜7日です。ご購入前に端末をご確認ください。法律で定められた場合を除き、お客様都合の返金はできません。",
    "cp.nav": "対応機種",
    "cp.crumb": "対応機種",
    "cp.h1": "お使いのスマホはeSIM対応？",
    "cp.intro": "eSIM対応機種リストを検索するか、1分でお手元のスマホを確認できます。物理SIMカードを使う場合の条件も下にまとめています。",
    "cp.j.search": "機種を検索",
    "cp.j.settings": "設定で確認",
    "cp.j.unlock": "SIMロック解除済み？",
    "cp.j.sim": "物理SIMを使う",
    "cp.j.list": "掲載機種一覧",
    "cp.tool.h2": "機種を検索",
    "cp.reset": "検索をクリア",
    "cp.list.p": "ブランドを開くと機種が表示されます。各ブランドの注記で、eSIM非対応の地域版を確認できます。",
    "cp.models": "{n}機種",
    "cp.set.p": "一番確実なのは、端末そのもので確認することです。",
    "cp.sim.h2": "LemonSIMの物理SIMカードを使う場合",
    "cp.sim.bands": "渡航先で使われている4Gバンドに端末が対応している必要もあります。端末の仕様表で確認できます。",
    "cp.faq": "よくある質問",
    "cp.q1": "リストにない機種でもeSIMは使えますか？",
    "cp.a1": "可能性はあります。リストはすべてを網羅していません。*#06# を入力するか設定を確認し、EIDや「eSIMを追加」が表示されればeSIM対応です。",
    "cp.q2": "購入した国や地域が関係するのはなぜ？",
    "cp.a2": "一部の機種は、国や地域によってeSIM非対応版が販売されています。リストの各ブランドの注記で、注意すべき版を確認できます。",
    "cp.q3": "SIMロックが解除されているか確認するには？",
    "cp.a3": "メーカーや販売店で一括購入した端末は通常ロックされていません。通信会社の契約とセットで購入した場合は、通信会社にお問い合わせください。iPhoneでは 設定 › 一般 › 情報 › SIMロック が「SIMロックなし」なら問題ありません。",
    "cp.q4": "eSIM非対応の場合は？",
    "cp.a4": "<a href=\"sim-card.html\">LemonSIMの物理SIMカード</a>は、SIMロックが解除され空きスロットがある端末で使えます。ご自宅に配送されるため、出発の1週間ほど前までにご注文ください。",
    "cp.guide": "対応機種ガイドを見る",
