    "dc.reset": "リセット",
    "dc.notice.ver": "この計算ツールのバージョンには対応していないため、初期設定を表示しています。",
    "dc.notice.bad": "リンク内の一部の設定を読み取れなかったため、初期値を使っています。",
    "dc.noscript": "表示中の結果は初期設定（アメリカ・7日間・ふつう）です。入力を変えるにはJavaScriptが必要です。",
    "dc.usage.p": "計算ツールが使う数値です。実際の使用量はアプリや設定、回線によって変わるため、計画の目安としてお使いください。",
    "dc.th.act": "項目",
    "dc.th.use": "使用量の目安",
    "dc.th.basis": "根拠",
    "dc.basis.est": "LemonSIMの推定",
    "dc.m.h3": "計算のしくみ",
    "dc.m.p1": "項目ごとに1日の量に低い値と高い値を掛けて合計し、日数を掛けると範囲になります。「目安」は上限に15%を足し、0.5GB単位で切り上げた値です。範囲は使い方の違いを表すもので、統計的な信頼区間ではありません。",
    "dc.m.p2": "動画はNetflixの公表値（モバイルのデータセーブで1時間約167MB、標準画質0.7～1GB、HDは最大3GB）を使っています。音楽はSpotifyのビットレート（96～320kbit/s、ロスレスは対象外）から換算しています。ビデオ通話はZoomの1対1通話の推奨帯域から上り下りを合わせて換算したもので、他のアプリでは異なります。それ以外はLemonSIMの推定値です。",
    "dc.m.p3": "含まれないもの：アプリやOSのアップデート、写真のクラウドバックアップ、大きなダウンロード。これらはWi-Fiで行うか、その分の時間を足してください。テザリング自体で数値は変わりません。接続したPCやタブレットで行う作業の分を合計に加えてください。",
    "dc.m.p4": "単位は10進法（1GB＝1,000MB）です。計算ツール バージョン1、数値の更新：2026年11月。",
    "dc.ex1.t": "週末の都市旅行",
    "dc.ex1.d": "3日間・ライト",
    "dc.ex2.t": "日本で2週間",
    "dc.ex2.d": "14日間・ふつう",
    "dc.ex3.t": "1か月のリモートワーク",
    "dc.ex3.d": "30日間・ふつう＋1日3時間のノートPC作業と1時間のビデオ通話",
    "dc.ex.load": "この例で計算する",
    "dc.save.1": "出発前に滞在先のオフラインマップを保存する。",
    "dc.save.2": "SNSアプリで動画の自動再生をオフにする。",
    "dc.save.3": "ドラマやプレイリストはWi-Fiでダウンロードしておく。",
    "dc.save.4": "写真のクラウドバックアップとアプリ更新はWi-Fiまで止めておく。",
    "dc.save.5": "旅行用回線で「省データモード」（iPhone）や「データセーバー」（Android）をオンにする。",
    "dc.save.more": "詳しい設定手順：<a href=\"https://www.lemonsim.com/blog/esim-data-saving-settings-iphone-android\">iPhoneとAndroidでeSIMのデータを節約する方法</a>（英語）",
    "dc.q1": "1日1GBで足りますか？",
    "dc.a1": "地図、メッセージ、SNS、少しのショート動画なら、たいてい足ります。動画視聴や長いビデオ通話、ノートPCでの作業があると1日数GB使うこともあります。ご自身の使用時間で計算してみてください。",
    "dc.q2": "テザリングをするとデータを多く使いますか？",
    "dc.a2": "テザリング自体ではなく、接続した機器がデータを使います。ノートPCはバックグラウンドで同期や更新をすることが多いので、その分も見積もりに加えてください。テザリングはすべてのLemonSIMプランで使えます。",
    "dc.q3": "データを使い切ったら？",
    "dc.a3": "eSIMプランはチャージできないため、残りの旅行用に別のeSIMプランを購入してください。LemonSIMの物理SIMカードは <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a> でチャージできます。",
    "dc.q4": "なぜ目安より大きいプランが表示されるのですか？",
    "dc.a4": "範囲の上限に15%を足した量を基準に、その容量があり旅行期間をカバーする最安のプランを選んでいます。プランの容量は決まっているため、目安よりかなり大きくなることがあります。",
    "dc.cta.q": "必要なデータ量がわからない？",
