    "ab.eyebrow": "LemonSIM 소개",
    "ab.h1": "더 멀리, 늘 연결된 채로.",
    "ab.sub": "LemonSIM은 해외 여행자가 방문하는 곳에 맞는 eSIM과 유심 요금제로 인터넷에 연결되도록 돕습니다.",
    "ab.chip1": "eSIM 여행지 13곳",
    "ab.chip2": "유심 지역 3곳",
    "ab.chip3": "24시간 지원",
    "ab.t1": "번거로움 없는 여행 연결",
    "ab.t2": "LemonSIM은 집을 떠나 안정적인 모바일 데이터가 필요한 사람들을 위한 여행 통신 서비스입니다. 여행지별 eSIM과 유심을 한곳에서 알기 쉽게 제공합니다.",
    "ab.t3": "목표는 간단합니다. 여행자가 알맞은 요금제를 고르고 사용법을 이해해 여행 전이나 여행 중에 안심하고 연결되도록 돕는 것입니다.",
    "ab.t4": "우리의 미션",
    "ab.t5": "모바일 연결을 여행의 자연스러운 일부로",
    "ab.t6": "명확한 요금제 정보, 간단한 설정 안내, 여행 내내 유용한 지원으로 여행 데이터의 불확실성을 없앱니다.",
    "ab.t7": "명확한 선택, 실용적인 지원, 더 잘 연결된 여행.",
    "ab.t8": "한눈에 보기",
    "ab.t9": "LemonSIM 한눈에 보기",
    "ab.t10": "여행지, 기기, 여행 기간에 맞춘 유연한 여행 연결.",
    "ab.f1t": "eSIM 여행지",
    "ab.f1p": "미국과 일본부터 유럽, 모로코까지 여행지마다 전용 요금제가 있습니다.",
    "ab.f2t": "유심 지역",
    "ab.f2p": "미국, 유럽, 일본 유심을 약 5~7일 안에 배송합니다.",
    "ab.f3n": "선불",
    "ab.f3t": "약정 없음",
    "ab.f3p": "필요한 데이터와 기간만 고르세요. 장기 약정이 없습니다.",
    "ab.f4t": "이메일 지원",
    "ab.f4p": "여행 전이나 여행 중 언제든 info@lemonsim.com으로 메일을 보내세요.",
    "ab.t11": "변화",
    "ab.t12": "연결 관리에 쓰는 시간은 줄이고, 여행을 즐기는 시간은 늘리세요.",
    "ab.t13": "여행자에게 가장 중요한 순간에 집중합니다.",
    "ab.t14": "도착하자마자 사용",
    "ab.t15": "미리 준비해 여행이 시작되면 바로 지도, 메시지, 예약, 교통 정보를 쓸 수 있습니다.",
    "ab.t16": "예측 가능한 비용",
    "ab.t17": "데이터, 기간, 가격이 명확한 선불 요금제를 비교하세요.",
    "ab.t18": "더 쉬운 선택",
    "ab.t19": "관련 없는 요금제를 뒤질 필요 없이 여행지별 요금제를 찾으세요.",
    "ab.t20": "우리의 가치",
    "ab.t21": "일하는 방식",
    "ab.t22": "명확함이 먼저",
    "ab.t23": "요금제, 가격, 설정을 쉬운 말로 설명해 여행자가 잘 알고 선택하도록 합니다.",
    "ab.t24": "실용적인 설계",
    "ab.t25": "모든 경험은 실제 여행의 필요를 해결하고 쓰기 쉬워야 합니다.",
    "ab.t26": "믿을 수 있는 지원",
    "ab.t27": "집에서 멀리 있을 때 연결이 가장 중요하므로 안내와 지원은 실용적이어야 합니다.",
    "ab.t28": "경계 없는 여행",
    "ab.t29": "연결되어 있으면 더 자유롭고 자신 있게 여행할 수 있다고 믿습니다.",
    "ab.t30": "우리 팀",
    "ab.t31": "연결된 여행을 잘 아는 사람들이 만듭니다",
    "ab.t32": "LemonSIM은 여행 통신, 디지털 제품, 콘텐츠, 고객 지원 경험을 한데 모았습니다. 분야를 넘나들며 하나의 기준으로 일합니다. 여행자의 모든 단계를 더 명확하게 만드는 것입니다.",
    "ab.t33": "팀에 문의하기",
    "co.h1": "무엇을 도와드릴까요?",
    "co.sub": "언제든 이메일을 보내 주세요. 24시간 지원합니다.",
