    "co.t16": "제품, 여행지, 기기, 도움이 필요한 단계를 파악합니다.",
    "co.t17": "세부 사항을 확인합니다",
    "co.t18": "빠진 정보가 있으면 계속 진행하는 데 필요한 것만 요청합니다.",
