    "co.t21": "이미 여행 중이신가요?",
    "co.t22": "먼저 간단히 확인해 보세요",
    "co.t23": "LemonSIM 회선이 켜져 있고 모바일 데이터용으로 선택되어 있으며 데이터 로밍이 켜져 있는지 확인한 뒤 기기를 재시작하세요. 그래도 연결되지 않으면 휴대폰 기종과 요금제 정보를 준비해 지원 페이지를 방문하세요.",
    "co.t24": "설정 도움 받기",
    "su.t1": "알맞은 설정 가이드를 찾고, 자주 쓰는 연결 설정을 확인하고, 지원팀에 필요한 정보를 준비하세요.",
    "su.t2": "여기서 시작",
    "su.t3": "모바일 데이터가 안 될 때",
    "su.t4": "문의 준비하기",
    "su.t5": "더 많은 답변",
    "su.t6": "LemonSIM 제품에 맞는 가이드를 고르세요. eSIM은 데이터가 필요하기 직전에 Wi-Fi에서 설치하세요. 요금제는 설치할 때 시작됩니다.",
