    "su.t14": "APN 확인: eSIM은 보통 자동으로 설정되며, LemonSIM 유심은 안내서의 APN을 따르세요.",
    "su.t15": "여행지, eSIM/유심 여부, 휴대폰 기종, 요금제 이름, 문제에 대한 짧은 설명을 적어 주세요. 오류 메시지가 있으면 그대로 적어 주세요.",
    "su.t16": "비밀번호, 전체 결제 정보, eSIM 활성화 코드는 절대 공개하거나 보내지 마세요.",
