    "cmp.fast.note": "eSIM 지원 여부만 확인됩니다.",
    "cmp.listnote": "목록 업데이트: 2026년 11월. 지역별 모델이 다를 수 있습니다.",
    "rv.line": "LemonSIM 고객지원팀 검토 · 2026년 11월 3일 · <a href=\"editorial-policy.html\">편집 기준</a>",
    "ed.h1": "편집 기준",
    "ed.intro": "이 웹사이트의 정보를 작성하고 확인하고 바로잡는 방법입니다.",
    "ed.s1": "담당",
    "ed.s1.p": "LemonSIM 고객지원 및 콘텐츠팀이 구매 정보와 여행 데이터 가이드를 담당합니다.",
    "ed.s2": "정보 확인 방법",
    "ed.s2.p": "가이드를 게시하거나 검토하기 전에 제조사 자료, 통신사 또는 제휴 네트워크 정보, LemonSIM 요금제 정보를 확인합니다. 내용을 확인하는 데 도움이 되면 출처 링크를 답니다. <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">호환 기종 목록</a>은 참고용이며 모든 지역별 모델을 보장하지는 않습니다.",
    "ed.s3": "검토와 날짜",
    "ed.s3.p": "\"검토\" 날짜는 그날 우리 팀이 페이지의 사실 정보와 관련 출처를 확인했다는 뜻입니다. 검토 결과 변경이 필요 없을 수도 있습니다. 검토 날짜는 검토를 마친 뒤에만 바꿉니다.",
    "ed.s4": "정정",
    "ed.s4.p": "오류를 발견하면 페이지 링크와 잘못된 내용을 <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>로 보내 주세요. 확인 후 오류가 맞으면 바로잡습니다. 페이지 전체를 다시 검토하면 검토 날짜를 업데이트합니다.",
    "ed.s5": "상업적 투명성",
    "ed.s5.p": "LemonSIM은 이 웹사이트에서 소개하는 요금제를 판매합니다. 가이드는 자사 제품과 이용 조건을 설명합니다. 후원 콘텐츠나 유료 게재가 있으면 분명히 표시합니다.",
    "ab.w.eyebrow": "이용 안내",
    "ab.w.h2": "LemonSIM에서 기대할 수 있는 것",
    "ab.w1t": "판매 상품",
    "ab.w1p": "13개 여행지 eSIM 요금제와 미국·유럽·일본 유심. 모든 요금제 페이지에 데이터, 유효기간, 가격, 제휴 네트워크가 나와 있습니다.",
    "ab.w2t": "필요할 때 도움",
    "ab.w2p": "여행 전과 여행 중 언제든 <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>로 이메일 지원을 받을 수 있습니다(24시간).",
    "ab.w3t": "명확한 정책",
    "ab.w3p": "구매 전에 <a href=\"refund-policy.html\">환불 정책</a>, <a href=\"terms-of-service.html\">이용약관</a>, <a href=\"privacy-policy.html\">개인정보처리방침</a>, <a href=\"editorial-policy.html\">편집 기준</a>을 확인하세요.",
    "ab.w4t": "안전한 결제",
    "ab.w4p": "결제는 Stripe로 처리되므로 전체 카드 번호는 저희가 아닌 Stripe로 전달됩니다.",
    "ab.w5t": "팔로우",
    "ab.w5p": "<a href=\"https://www.facebook.com/share/1DepLp294g/?mibextid=wwXIfr\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a>, <a href=\"https://instagram.com/support.lemonsim\" target=\"_blank\" rel=\"noopener noreferrer\">Instagram</a>, <a href=\"https://www.youtube.com/@Lemonsim-i9t\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a>, <a href=\"https://x.com/Lemonsimc\" target=\"_blank\" rel=\"noopener noreferrer\">X</a>에서 LemonSIM을 팔로우하세요.",
    "ab.w.cta": "팀에 문의하기",
    "ft.tag": "여행자를 위한 선불 eSIM과 유심.",
    "tr.stripe": "Stripe 보안 결제",
    "tr.support": "24시간 이메일 지원",
    "tr.check": "호환성 확인",
    "tr.refund": "환불 정책",
    "pd.buy2.esim": "구매 전에 휴대폰을 확인해 주세요. 법률상 요구되는 경우를 제외하고 단순 변심 환불은 불가합니다.",
    "pd.buy2.sim": "배송은 보통 5~7일 걸립니다. 구매 전에 휴대폰을 확인해 주세요. 법률상 요구되는 경우를 제외하고 단순 변심 환불은 불가합니다.",
    "cp.nav": "기기 호환성",
    "cp.crumb": "호환 기종",
    "cp.h1": "내 휴대폰은 eSIM을 지원할까요?",
    "cp.intro": "eSIM 지원 기종 목록에서 검색하거나 1분 만에 휴대폰에서 직접 확인하세요. 유심을 쓰실 예정이라면 아래에서 함께 확인할 수 있습니다.",
    "cp.j.search": "기종 검색",
    "cp.j.settings": "설정에서 확인",
    "cp.j.unlock": "통신사 잠금 해제?",
    "cp.j.sim": "유심 사용",
    "cp.j.list": "전체 기종",
    "cp.tool.h2": "휴대폰 기종 검색",
    "cp.reset": "검색 지우기",
    "cp.list.p": "브랜드를 펼치면 기종이 보입니다. 브랜드 아래 안내에서 eSIM을 지원하지 않는 지역별 모델을 확인하세요.",
    "cp.models": "{n}개 기종",
    "cp.set.p": "가장 확실한 방법은 휴대폰에서 직접 확인하는 것입니다.",
    "cp.sim.h2": "LemonSIM 유심을 사용하는 경우",
    "cp.sim.bands": "여행지에서 쓰는 4G 주파수 대역도 지원해야 합니다. 휴대폰 사양에서 확인할 수 있습니다.",
    "cp.faq": "자주 묻는 질문",
    "cp.q1": "목록에 없는 휴대폰도 eSIM을 쓸 수 있나요?",
    "cp.a1": "가능할 수 있습니다. 목록이 완전하지는 않습니다. *#06#을 누르거나 설정을 확인해 EID나 \"eSIM 추가\" 메뉴가 보이면 eSIM을 지원합니다.",
    "cp.q2": "휴대폰을 어디서 샀는지가 왜 중요한가요?",
    "cp.a2": "일부 기종은 국가에 따라 eSIM이 없는 버전으로 판매됩니다. 목록의 브랜드별 안내에서 주의할 버전을 확인하세요.",
    "cp.q3": "통신사 잠금이 해제됐는지 어떻게 알 수 있나요?",
    "cp.a3": "제조사나 판매점에서 일시불로 산 휴대폰은 보통 잠금이 없습니다. 통신사 약정으로 샀다면 통신사에 문의하세요. iPhone은 설정 › 일반 › 정보 › 이동통신사 잠금이 \"SIM 제한 없음\"이면 됩니다.",
    "cp.q4": "휴대폰이 eSIM을 지원하지 않으면요?",
    "cp.a4": "<a href=\"sim-card.html\">LemonSIM 유심</a>은 잠금이 해제되고 빈 SIM 슬롯이 있는 휴대폰이면 사용할 수 있습니다. 주소로 배송되니 출발 일주일 전쯤 주문하세요.",
    "cp.guide": "전체 호환성 가이드",
