    "dc.r.top": "데이터를 많이 쓰는 활동",
    "dc.r.match": "조건에 맞는 최저가 요금제",
    "dc.r.see": "이 요금제 보기",
    "dc.r.next": "한 단계 큰 요금제:",
    "dc.r.nodays": "{n}일을 하나로 커버하는 요금제는 없습니다. 요금제는 최대 {max}일이며 eSIM 요금제는 충전할 수 없습니다.",
    "dc.r.nodata": "이 기간에 {gb}를 제공하는 단일 요금제는 없습니다.",
    "dc.r.unl": "{country}는 무제한 요금제만 있어 여행 기간을 모두 커버하는 가장 저렴한 요금제를 보여 드립니다.",
    "dc.r.unlalso": "{country}에는 무제한 요금제도 있습니다. 요금제 페이지에서 자세히 확인하세요.",
    "dc.r.all": "{country} 요금제 전체 보기",
    "dc.r.other": "위에서 여행지를 고르면 맞는 요금제가 표시됩니다. <a href=\"esim.html\">전체 eSIM 여행지 보기</a>",
    "dc.reset": "초기화",
    "dc.notice.ver": "지원하지 않는 계산기 버전이라 기본 설정을 표시합니다.",
    "dc.notice.bad": "링크의 일부 설정을 읽지 못해 기본값을 사용합니다.",
    "dc.noscript": "표시된 결과는 기본 설정(미국, 7일, 보통) 기준입니다. 값을 바꾸려면 JavaScript가 필요합니다.",
    "dc.usage.p": "계산기에 쓰이는 수치입니다. 실제 사용량은 앱, 설정, 네트워크에 따라 달라지므로 계획용 참고치로 보세요.",
    "dc.th.act": "활동",
    "dc.th.use": "예상 사용량",
    "dc.th.basis": "근거",
    "dc.basis.est": "LemonSIM 추정",
    "dc.m.h3": "계산 방법",
    "dc.m.p1": "활동마다 하루 사용량에 낮은 값과 높은 값을 곱해 더한 뒤 일수를 곱하면 범위가 나옵니다. \"준비 권장\"은 상한에 15%를 더해 0.5GB 단위로 올림한 값입니다. 범위는 사용 상황의 차이를 나타내며 통계적 신뢰구간이 아닙니다.",
    "dc.m.p2": "동영상은 넷플릭스 공개 수치(모바일 데이터 절약 시 시간당 약 167MB, 표준 화질 0.7~1GB, HD 최대 3GB)를 씁니다. 음악은 스포티파이 비트레이트(96~320kbit/s, 무손실 제외)로 환산했습니다. 영상통화는 줌의 1:1 통화 권장 대역폭을 업로드와 다운로드 합산으로 환산했으며 다른 앱은 다를 수 있습니다. 나머지는 LemonSIM 추정치입니다.",
    "dc.m.p3": "포함되지 않는 것: 앱·시스템 업데이트, 사진 클라우드 백업, 대용량 다운로드. 이런 작업은 Wi-Fi에서 하거나 시간을 따로 더하세요. 핫스팟 자체는 수치를 바꾸지 않습니다. 핫스팟에 연결한 노트북이나 태블릿에서 하는 활동을 합계에 더하면 됩니다.",
    "dc.m.p4": "단위는 십진법(1GB = 1,000MB)입니다. 계산기 버전 1, 수치 업데이트 2026년 11월.",
    "dc.ex1.t": "주말 도시 여행",
    "dc.ex1.d": "3일, 가볍게",
    "dc.ex2.t": "일본 2주 여행",
    "dc.ex2.d": "14일, 보통",
    "dc.ex3.t": "한 달 원격 근무",
    "dc.ex3.d": "30일, 보통 + 하루 노트북 작업 3시간과 영상통화 1시간",
    "dc.ex.load": "이 예시 불러오기",
    "dc.save.1": "출발 전에 도시 오프라인 지도를 내려받으세요.",
    "dc.save.2": "SNS 앱의 동영상 자동 재생을 끄세요.",
    "dc.save.3": "드라마와 플레이리스트는 Wi-Fi에서 미리 내려받으세요.",
    "dc.save.4": "사진 클라우드 백업과 앱 업데이트는 Wi-Fi에서 하세요.",
    "dc.save.5": "여행용 회선에 저데이터 모드(iPhone)나 데이터 절약 모드(Android)를 켜세요.",
    "dc.save.more": "자세한 설정 방법: <a href=\"https://www.lemonsim.com/blog/esim-data-saving-settings-iphone-android\">iPhone과 Android에서 eSIM 데이터 절약하기</a>(영문)",
    "dc.q1": "하루 1GB면 충분한가요?",
    "dc.a1": "지도, 메시지, SNS, 약간의 숏폼 영상이라면 대개 충분합니다. 동영상 시청, 긴 영상통화, 노트북 작업은 하루 몇 GB를 쓸 수 있습니다. 직접 시간을 넣어 계산해 보세요.",
    "dc.q2": "핫스팟을 쓰면 데이터가 더 드나요?",
    "dc.a2": "핫스팟 자체가 아니라 연결된 기기가 데이터를 씁니다. 노트북은 백그라운드에서 동기화와 업데이트를 자주 하니 그 활동도 예상치에 더하세요. 핫스팟은 모든 LemonSIM 요금제에서 쓸 수 있습니다.",
    "dc.q3": "데이터를 다 쓰면 어떻게 되나요?",
    "dc.a3": "eSIM 요금제는 충전할 수 없으니 남은 일정용으로 eSIM 요금제를 하나 더 구매하세요. LemonSIM 유심은 <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a>에서 충전할 수 있습니다.",
    "dc.q4": "왜 예상치보다 큰 요금제를 추천하나요?",
    "dc.a4": "범위 상한에 15%를 더한 양을 기준으로, 그만큼의 데이터가 있고 여행 기간을 모두 커버하는 가장 저렴한 요금제를 고릅니다. 요금제 용량은 정해져 있어 예상치보다 꽤 클 수 있습니다.",
    "dc.cta.q": "데이터가 얼마나 필요한지 모르겠다면?",
