    "ab.eyebrow": "Sobre LemonSIM",
    "ab.h1": "Viaja más lejos. Sigue conectado.",
    "ab.sub": "LemonSIM ayuda a los viajeros internacionales a conectarse con planes eSIM y de tarjeta SIM para los lugares que visitan.",
    "ab.chip1": "13 destinos eSIM",
    "ab.chip2": "3 regiones con tarjeta SIM",
    "ab.chip3": "Soporte 24/7",
    "ab.t1": "Conectividad de viaje sin complicaciones",
    "ab.t2": "LemonSIM es un servicio de conectividad para quienes necesitan datos móviles fiables lejos de casa. Reunimos opciones de eSIM y tarjeta SIM física por destino en una experiencia clara.",
    "ab.t3": "Nuestro objetivo es sencillo: ayudar a los viajeros a elegir el plan adecuado, entender cómo funciona y conectarse con confianza antes o durante el viaje.",
    "ab.t4": "Nuestra misión",
    "ab.t5": "Que la conexión móvil sea una parte natural del viaje",
    "ab.t6": "Eliminamos la incertidumbre de los datos de viaje con información clara de los planes, guías de configuración sencillas y soporte útil durante todo el viaje.",
    "ab.t7": "Opciones claras. Soporte práctico. Viajes mejor conectados.",
    "ab.t8": "Datos rápidos",
    "ab.t9": "LemonSIM de un vistazo",
    "ab.t10": "Conectividad flexible según el destino, el dispositivo y la duración del viaje.",
    "ab.f1t": "destinos eSIM",
    "ab.f1p": "De EE. UU. y Japón a Europa y Marruecos, cada uno con sus propios planes.",
    "ab.f2t": "regiones con tarjeta SIM",
    "ab.f2p": "Tarjetas SIM físicas para EE. UU., Europa y Japón, entregadas en unos 5–7 días.",
    "ab.f3n": "Prepago",
    "ab.f3t": "Sin contrato",
    "ab.f3p": "Elige los datos y la validez que necesitas, sin contrato a largo plazo.",
    "ab.f4t": "Soporte por correo",
    "ab.f4p": "Escribe a info@lemonsim.com en cualquier momento, antes o durante tu viaje.",
    "ab.t11": "Impacto",
    "ab.t12": "Menos tiempo gestionando la conexión. Más tiempo disfrutando del viaje.",
    "ab.t13": "Nos centramos en los momentos que más importan a los viajeros.",
    "ab.t14": "Listo al llegar",
    "ab.t15": "Prepárate con antelación para tener mapas, mensajes, reservas y transporte desde el inicio del viaje.",
    "ab.t16": "Costes más previsibles",
    "ab.t17": "Compara opciones prepago con datos, validez y precios claros.",
    "ab.t18": "Decisiones más sencillas",
    "ab.t19": "Encuentra opciones para tu destino sin revisar planes que no te sirven.",
    "ab.t20": "Nuestros valores",
    "ab.t21": "Cómo trabajamos",
    "ab.t22": "Primero, la claridad",
    "ab.t23": "Explicamos planes, precios y configuración con palabras sencillas para que elijas con información.",
    "ab.t24": "Útil por diseño",
    "ab.t25": "Cada parte de la experiencia debe resolver una necesidad real del viaje y ser fácil de usar.",
    "ab.t26": "Soporte fiable",
    "ab.t27": "La conexión importa más cuando estás lejos de casa, así que la ayuda debe ser práctica.",
    "ab.t28": "Viajar sin fronteras",
    "ab.t29": "Creemos que estar conectado ayuda a moverse con más libertad y confianza.",
    "ab.t30": "Nuestro equipo",
    "ab.t31": "Creado por personas que entienden el viaje conectado",
    "ab.t32": "LemonSIM reúne experiencia en conectividad de viaje, productos digitales, contenido y atención al cliente. Trabajamos con un criterio común: que cada paso sea más claro para el viajero.",
    "ab.t33": "Habla con nuestro equipo",
    "co.h1": "¿Cómo podemos ayudarte?",
    "co.sub": "Escríbenos cuando quieras: soporte disponible 24/7.",
