    "co.t2": "¿Qué necesitas?",
    "co.t3": "Elegir un plan",
    "co.t4": "Compara planes, datos y validez por destino antes de viajar.",
    "co.t5": "Ver planes eSIM",
    "co.t6": "Ver tarjetas SIM",
    "co.t7": "Configuración y problemas",
    "co.t8": "Ayuda con instalación, activación, ajustes de datos, APN o conexión.",
