    "co.t14": "Soporte centrado en el problema",
    "co.t15": "Revisamos la solicitud",
    "co.t16": "Identificamos el producto, el destino, el dispositivo y en qué paso necesitas ayuda.",
    "co.t17": "Aclaramos los detalles",
    "co.t18": "Si falta algo, solo pedimos la información necesaria para continuar.",
