    "co.t20": "Recibes instrucciones prácticas o la mejor vía para resolver la solicitud.",
    "co.t21": "¿Ya estás de viaje?",
    "co.t22": "Empieza con unas comprobaciones rápidas",
    "co.t23": "Comprueba que la línea LemonSIM esté activa, elegida para datos móviles y con el roaming de datos activado, y reinicia el dispositivo. ¿Sigue sin conexión? Ve a Soporte con el modelo de teléfono y los datos del plan.",
    "co.t24": "Obtener ayuda con la configuración",
    "su.t1": "Encuentra la guía adecuada, revisa los ajustes de conexión habituales y prepara los datos que necesita nuestro equipo.",
    "su.t2": "Empieza aquí",
    "su.t3": "Si los datos móviles no funcionan",
    "su.t4": "Prepara tu solicitud de soporte",
    "su.t5": "Más respuestas",
    "su.t6": "Elige la guía de tu producto LemonSIM. Instala la eSIM con Wi-Fi poco antes de necesitar datos: el plan empieza al instalarla.",
    "su.t7": "Cómo configurar una eSIM",
    "su.t8": "Cómo usar una tarjeta SIM",
    "su.t9": "Revisa estos ajustes antes de pedir más ayuda:",
    "su.t10": "Comprueba que la línea LemonSIM esté activa y elegida para datos móviles.",
    "su.t11": "Activa el roaming de datos para la línea LemonSIM.",
    "su.t12": "Activa el modo avión 30 segundos y luego desactívalo.",
    "su.t13": "Reinicia el dispositivo y espera unos minutos a que se registre en la red.",
    "su.t14": "Revisa el APN: las eSIM suelen configurarlo solas; con una tarjeta SIM LemonSIM, sigue el APN de sus instrucciones.",
    "su.t15": "Incluye tu destino, si es eSIM o tarjeta SIM, el modelo de teléfono, el nombre del plan y una breve descripción del problema. Añade el mensaje de error exacto si aparece.",
    "su.t16": "Nunca publiques ni envíes contraseñas, datos de pago completos ni el código de activación de la eSIM.",
