    "cmp.fast.note": "Solo muestra si admite eSIM.",
    "cmp.listnote": "Lista actualizada en nov. 2026. Los modelos varían según la región.",
    "rv.line": "Revisado por el equipo de soporte de LemonSIM · 3 de noviembre de 2026 · <a href=\"editorial-policy.html\">Normas editoriales</a>",
    "ed.h1": "Normas editoriales",
    "ed.intro": "Cómo escribimos, comprobamos y corregimos la información de este sitio.",
    "ed.s1": "Quién es responsable",
    "ed.s1.p": "El equipo de soporte y contenidos de LemonSIM es responsable de la información de compra y de las guías de conectividad para viajes.",
    "ed.s2": "Cómo comprobamos la información",
    "ed.s2.p": "Antes de publicar o revisar una guía, comprobamos la documentación de los fabricantes, la información de operadores o redes asociadas y los datos de los planes de LemonSIM. Enlazamos las fuentes cuando te ayudan a verificar algo. Nuestra <a href=\"esim-compatible-phones.html\" data-compat=\"esim\">lista de compatibilidad</a> es una referencia, no una garantía para cada modelo regional.",
    "ed.s3": "Revisiones y fechas",
    "ed.s3.p": "\"Revisado\" significa que nuestro equipo comprobó en esa fecha los datos de la página y sus fuentes. Una revisión puede confirmar que no hace falta ningún cambio. Solo cambiamos la fecha después de completar una revisión.",
    "ed.s4": "Correcciones",
    "ed.s4.p": "Para informar de un error, escribe a <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a> con el enlace de la página y el dato que crees incorrecto. Investigaremos y corregiremos los errores confirmados. Cuando revisemos la página completa, actualizaremos su fecha de revisión.",
    "ed.s5": "Transparencia comercial",
    "ed.s5.p": "LemonSIM vende los planes que se describen en este sitio. Nuestras guías explican nuestros productos y sus requisitos. Señalaremos claramente cualquier contenido patrocinado o publicidad pagada.",
    "ab.w.eyebrow": "Trabajar con nosotros",
    "ab.w.h2": "Qué puedes esperar de LemonSIM",
    "ab.w1t": "Qué vendemos",
    "ab.w1p": "Planes eSIM para 13 destinos y tarjetas SIM para EE. UU., Europa y Japón. Cada página de plan indica datos, validez, precio y redes asociadas.",
    "ab.w2t": "Ayuda cuando la necesitas",
    "ab.w2p": "Soporte por correo 24/7 en <a href=\"mailto:info@lemonsim.com\">info@lemonsim.com</a>, antes y durante tu viaje.",
    "ab.w3t": "Políticas claras",
    "ab.w3p": "Lee nuestra <a href=\"refund-policy.html\">Política de reembolso</a>, los <a href=\"terms-of-service.html\">Términos</a>, la <a href=\"privacy-policy.html\">Política de privacidad</a> y las <a href=\"editorial-policy.html\">Normas editoriales</a> antes de comprar.",
    "ab.w4t": "Pago seguro",
    "ab.w4p": "El pago funciona con Stripe: tu número de tarjeta completo va a Stripe, no a nosotros.",
    "ab.w5t": "Encuéntranos",
    "ab.w5p": "Sigue a LemonSIM en <a href=\"https://www.facebook.com/share/1DepLp294g/?mibextid=wwXIfr\" target=\"_blank\" rel=\"noopener noreferrer\">Facebook</a>, <a href=\"https://instagram.com/support.lemonsim\" target=\"_blank\" rel=\"noopener noreferrer\">Instagram</a>, <a href=\"https://www.youtube.com/@Lemonsim-i9t\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a> y <a href=\"https://x.com/Lemonsimc\" target=\"_blank\" rel=\"noopener noreferrer\">X</a>.",
    "ab.w.cta": "Habla con nuestro equipo",
