    "pd.buy2.sim": "La entrega suele tardar 5–7 días. Comprueba tu teléfono antes de comprar: no hay reembolsos por cambio de opinión, salvo cuando lo exija la ley.",
    "cp.nav": "Compatibilidad",
    "cp.crumb": "Teléfonos compatibles",
    "cp.h1": "¿Tu teléfono es compatible con eSIM?",
    "cp.intro": "Busca en nuestra lista de teléfonos con eSIM o revisa tu teléfono en un minuto. ¿Prefieres una SIM física? También lo explicamos abajo.",
    "cp.j.search": "Buscar modelos",
