    "cp.reset": "Borrar búsqueda",
    "cp.list.p": "Abre una marca para ver sus modelos. La nota de cada marca indica qué versiones regionales no tienen eSIM.",
    "cp.models": "{n} modelos",
    "cp.set.p": "La forma más segura es mirarlo en el propio teléfono.",
    "cp.sim.h2": "Si usas una SIM física de LemonSIM",
    "cp.sim.bands": "Tu teléfono también debe admitir las bandas 4G del destino. Las encontrarás en sus especificaciones.",
    "cp.faq": "Preguntas frecuentes",
    "cp.q1": "Mi teléfono no está en la lista. ¿Puedo usar una eSIM?",
    "cp.a1": "Es posible. Nuestra lista no está completa. Marca *#06# o revisa Ajustes: si ves un EID o la opción «Añadir eSIM», tu teléfono tiene eSIM.",
    "cp.q2": "¿Por qué importa dónde compré mi teléfono?",
    "cp.a2": "Algunos modelos se venden sin eSIM en ciertos países. La nota de cada marca en la lista indica qué versiones revisar.",
    "cp.q3": "¿Cómo sé si mi teléfono está liberado?",
    "cp.a3": "Los teléfonos comprados directamente al fabricante o a una tienda suelen estar liberados. Si lo obtuviste con un contrato de operador, pregúntale a tu operador. En iPhone, Ajustes › General › Información › Bloqueo del operador debe indicar «Sin restricciones de SIM».",
    "cp.q4": "¿Y si mi teléfono no admite eSIM?",
    "cp.a4": "Una <a href=\"sim-card.html\">tarjeta SIM física LemonSIM</a> funciona en cualquier teléfono liberado con una ranura libre. Se envía a tu dirección, así que pídela una semana antes de viajar.",
