    "dc.reset": "Restablecer",
    "dc.notice.ver": "Esta versión de la calculadora no es compatible; se muestran los valores predeterminados.",
    "dc.notice.bad": "Algunos ajustes del enlace no se pudieron leer y se usan los predeterminados.",
    "dc.noscript": "El resultado es para los valores predeterminados (EE. UU., 7 días, Normal). Para cambiarlos se necesita JavaScript.",
    "dc.usage.p": "Son los valores que usa la calculadora. El consumo real depende de la app, sus ajustes y la red, así que tómalos como referencia.",
    "dc.th.act": "Actividad",
    "dc.th.use": "Consumo estimado",
    "dc.th.basis": "Base",
    "dc.basis.est": "Estimación de LemonSIM",
    "dc.m.h3": "Cómo se calcula",
    "dc.m.p1": "Para cada actividad multiplicamos tu cantidad diaria por un valor bajo y uno alto, sumamos y multiplicamos por los días. Así sale el rango. «Calcula» toma el extremo alto, añade un 15 % y redondea hacia arriba al siguiente 0,5 GB. El rango muestra escenarios distintos; no es un intervalo de confianza estadístico.",
    "dc.m.p2": "El streaming usa las cifras publicadas por Netflix: unos 167 MB por hora con Ahorro de datos en el móvil, 0,7–1 GB en calidad estándar y hasta 3 GB en HD. La música se calcula a partir de las tasas de bits de Spotify (96–320 kbit/s, sin lossless). Las videollamadas se calculan con el ancho de banda recomendado por Zoom para llamadas 1:1, sumando subida y bajada; otras apps varían. Todo lo demás es una estimación de LemonSIM.",
    "dc.m.p3": "No incluye: actualizaciones de apps y del sistema, copias de fotos en la nube ni descargas grandes. Hazlas con wifi o añade ese tiempo. El punto de acceso no cambia los valores: un portátil o tableta conectado consume según lo que haga, así que suma sus actividades.",
    "dc.m.p4": "Unidades decimales: 1 GB = 1000 MB. Calculadora versión 1, valores actualizados en noviembre de 2026.",
    "dc.ex1.t": "Escapada de fin de semana",
    "dc.ex1.d": "3 días, uso ligero",
    "dc.ex2.t": "Dos semanas en Japón",
    "dc.ex2.d": "14 días, uso normal",
    "dc.ex3.t": "Un mes de teletrabajo",
    "dc.ex3.d": "30 días, uso normal más 3 horas de portátil y 1 hora de videollamadas al día",
    "dc.ex.load": "Cargar este ejemplo",
    "dc.save.1": "Descarga mapas sin conexión de la ciudad antes de salir.",
    "dc.save.2": "Desactiva la reproducción automática en las redes sociales.",
    "dc.save.3": "Descarga series y listas con wifi en lugar de verlas en streaming.",
    "dc.save.4": "Pausa la copia de fotos en la nube y las actualizaciones hasta tener wifi.",
    "dc.save.5": "Activa Modo de datos reducidos (iPhone) o Ahorro de datos (Android) en la línea de viaje.",
    "dc.save.more": "Ajustes paso a paso: <a href=\"https://www.lemonsim.com/blog/esim-data-saving-settings-iphone-android\">cómo ahorrar datos de eSIM en iPhone y Android</a> (en inglés).",
    "dc.q1": "¿Basta con 1 GB al día?",
    "dc.a1": "Para mapas, mensajes, redes sociales y algunos vídeos cortos, normalmente sí. El streaming, las videollamadas largas o trabajar con un portátil pueden gastar varios GB al día. Usa la calculadora con tus propias horas.",
    "dc.q2": "¿El punto de acceso gasta más datos?",
    "dc.a2": "El punto de acceso en sí no, pero los dispositivos conectados sí. Los portátiles suelen sincronizar y actualizar en segundo plano, así que suma sus actividades. El punto de acceso funciona en todos los planes LemonSIM.",
    "dc.q3": "¿Qué pasa si me quedo sin datos?",
    "dc.a3": "Un plan eSIM no se puede recargar, así que compra otro plan eSIM para el resto del viaje. Una SIM física LemonSIM se puede recargar en <a href=\"https://topup.lemonsim.com\" target=\"_blank\" rel=\"noopener\">topup.lemonsim.com</a>.",
    "dc.q4": "¿Por qué sugiere un plan mayor que mi estimación?",
    "dc.a4": "Calcula con el extremo alto del rango más un 15 % y elige el plan más barato con al menos esos datos que dure todo el viaje. Los planes tienen tamaños fijos, así que puede quedar bastante por encima.",
    "dc.cta.q": "¿No sabes cuántos datos necesitas?",
